import"./chunk-ZW5NV4UO.js";var a={uk:{title:"\u0421\u043F\u0456\u043B\u044C\u043D\u043E\u0442\u0438 Mastodon \u0437\u0430 \u0456\u043D\u0442\u0435\u0440\u0435\u0441\u0430\u043C\u0438",description:"\u0417\u043D\u0430\u0439\u0434\u0438 \u0443\u043A\u0440\u0430\u0457\u043D\u043E\u043C\u043E\u0432\u043D\u0438\u0445 \u0430\u0432\u0442\u043E\u0440\u0456\u0432 \u0456 \u0442\u0435\u043C\u0438 \u043D\u0430 Mastodon. \u041F\u0435\u0440\u0435\u0433\u043B\u044F\u043D\u044C \u043F\u0443\u0431\u043B\u0456\u0447\u043D\u0456 \u0434\u043E\u043F\u0438\u0441\u0438 \u0442\u0430 \u043E\u0431\u0435\u0440\u0438, \u043D\u0430 \u043A\u043E\u0433\u043E \u0439 \u043D\u0430 \u0449\u043E \u043F\u0456\u0434\u043F\u0438\u0441\u0430\u0442\u0438\u0441\u044F.",eyebrow:"\u0421\u043F\u0456\u043B\u044C\u043D\u043E\u0442\u0438",openApp:"\u0412\u0456\u0434\u043A\u0440\u0438\u0442\u0438 Mawkingbird",heading:"\u0421\u043F\u0456\u043B\u044C\u043D\u043E\u0442\u0438 Mastodon \u0437\u0430 \u0456\u043D\u0442\u0435\u0440\u0435\u0441\u0430\u043C\u0438",intro:["\u0417\u043D\u0430\u0439\u0434\u0438 \u043B\u044E\u0434\u0435\u0439 \u0456 \u0442\u0435\u043C\u0438 \u043D\u0430 Mastodon, \u044F\u043A\u0456 \u0442\u043E\u0431\u0456 \u0446\u0456\u043A\u0430\u0432\u0456. \u041F\u0443\u0431\u043B\u0456\u0447\u043D\u0456 \u0434\u043E\u043F\u0438\u0441\u0438 \u043C\u043E\u0436\u043D\u0430 \u0447\u0438\u0442\u0430\u0442\u0438 \u0431\u0435\u0437 \u0440\u0435\u0454\u0441\u0442\u0440\u0430\u0446\u0456\u0457.","\u041A\u043E\u0436\u043D\u0430 \u0434\u043E\u0431\u0456\u0440\u043A\u0430 \u043E\u0431\u2019\u0454\u0434\u043D\u0443\u0454 \u0430\u043A\u0430\u0443\u043D\u0442\u0438 \u0439 \u0445\u0435\u0448\u0442\u0435\u0433\u0438 \u0437\u0430 \u0442\u0435\u043C\u043E\u044E. \u041E\u0431\u0438\u0440\u0430\u0439, \u0449\u043E \u0434\u043E\u0434\u0430\u0442\u0438 \u0434\u043E \u0441\u0432\u043E\u0454\u0457 \u0441\u0442\u0440\u0456\u0447\u043A\u0438."],moreHeading:"\u0411\u0456\u043B\u044C\u0448\u0435 \u043C\u043E\u0436\u043B\u0438\u0432\u043E\u0441\u0442\u0435\u0439",allLanguages:"\u0423\u0441\u0456 \u0442\u0435\u043C\u0438 \u0439 \u043C\u043E\u0432\u0438 (\u0430\u043D\u0433\u043B\u0456\u0439\u0441\u044C\u043A\u043E\u044E)",tools:"\u0411\u0435\u0437\u043A\u043E\u0448\u0442\u043E\u0432\u043D\u0456 \u0456\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0438 \u0434\u043B\u044F Mastodon \u0456 Bluesky (\u0430\u043D\u0433\u043B\u0456\u0439\u0441\u044C\u043A\u043E\u044E)",help:"\u0414\u043E\u043F\u043E\u043C\u043E\u0433\u0430 (\u0430\u043D\u0433\u043B\u0456\u0439\u0441\u044C\u043A\u043E\u044E)",features:"\u041F\u0440\u043E Mawkingbird (\u0430\u043D\u0433\u043B\u0456\u0439\u0441\u044C\u043A\u043E\u044E)"},nl:{title:"Mastodon-gemeenschappen per interesse",description:"Ontdek Nederlandstalige accounts en onderwerpen op Mastodon. Bekijk openbare berichten en kies wie en wat je wilt volgen.",eyebrow:"Gemeenschappen",openApp:"Mawkingbird openen",heading:"Mastodon-gemeenschappen per interesse",intro:["Ontdek mensen en onderwerpen op Mastodon die bij je interesses passen. Je kunt openbare berichten bekijken voordat je een account maakt.","Elke pagina brengt accounts en hashtags rond een onderwerp samen. Kies zelf wat je wilt volgen."],moreHeading:"Meer ontdekken",allLanguages:"Alle onderwerpen en talen (in het Engels)",tools:"Gratis tools voor Mastodon en Bluesky",help:"Hulp (in het Engels)",features:"Mawkingbird ontdekken (in het Engels)"},vi:{title:"C\u1ED9ng \u0111\u1ED3ng Mastodon theo s\u1EDF th\xEDch",description:"Kh\xE1m ph\xE1 c\u1ED9ng \u0111\u1ED3ng v\xE0 t\xE0i kho\u1EA3n \u0111\u1EC3 theo d\xF5i tr\xEAn Mastodon. Xem tr\u01B0\u1EDBc c\xE1c b\xE0i vi\u1EBFt c\xF4ng khai r\u1ED3i ch\u1ECDn theo s\u1EDF th\xEDch c\u1EE7a b\u1EA1n.",eyebrow:"C\u1ED9ng \u0111\u1ED3ng",openApp:"M\u1EDF Mawkingbird",heading:"C\u1ED9ng \u0111\u1ED3ng Mastodon theo s\u1EDF th\xEDch",intro:["Kh\xE1m ph\xE1 c\u1ED9ng \u0111\u1ED3ng Mastodon qua nh\u1EEFng t\xE0i kho\u1EA3n \u0111\u01B0\u1EE3c ch\u1ECDn. B\u1EA1n c\xF3 th\u1EC3 \u0111\u1ECDc b\xE0i vi\u1EBFt c\xF4ng khai tr\u01B0\u1EDBc khi t\u1EA1o t\xE0i kho\u1EA3n.","H\u01B0\u1EDBng d\u1EABn n\xE0y vi\u1EBFt b\u1EB1ng ti\u1EBFng Vi\u1EC7t. Ng\xF4n ng\u1EEF b\xE0i \u0111\u0103ng t\xF9y theo t\u1EEBng t\xE0i kho\u1EA3n; xem m\xF4 t\u1EA3 tr\xEAn m\u1ED7i trang."],moreHeading:"Kh\xE1m ph\xE1 th\xEAm",allLanguages:"M\u1ECDi ch\u1EE7 \u0111\u1EC1 v\xE0 ng\xF4n ng\u1EEF (b\u1EB1ng ti\u1EBFng Anh)",tools:"C\xF4ng c\u1EE5 mi\u1EC5n ph\xED cho Mastodon v\xE0 Bluesky (b\u1EB1ng ti\u1EBFng Anh)",help:"Tr\u1EE3 gi\xFAp (b\u1EB1ng ti\u1EBFng Anh)",features:"T\xEDnh n\u0103ng Mawkingbird (b\u1EB1ng ti\u1EBFng Anh)"},ms:{title:"Komuniti Mastodon mengikut minat",description:"Temui akaun dan komuniti untuk diikuti di Mastodon. Baca dahulu, kemudian pilih akaun yang sesuai dengan minat anda.",eyebrow:"Komuniti",openApp:"Buka Mawkingbird",heading:"Komuniti Mastodon mengikut minat",intro:["Temui komuniti di Mastodon melalui senarai akaun pilihan. Anda boleh membaca siaran awam sebelum membuka akaun.","Panduan ini ditulis dalam bahasa Melayu. Bahasa siaran berbeza mengikut akaun; lihat penerangan pada setiap halaman."],moreHeading:"Lagi",allLanguages:"Semua topik dan bahasa (dalam bahasa Inggeris)",tools:"Alat percuma untuk Mastodon dan Bluesky (dalam bahasa Inggeris)",help:"Bantuan (dalam bahasa Inggeris)",features:"Ciri Mawkingbird (dalam bahasa Inggeris)"},en:{title:"",description:"",eyebrow:"Communities",openApp:"Open Mawkingbird",heading:"Mastodon communities by interest",intro:["A new Mastodon account starts with an empty timeline. Each page gathers one interest: the hashtags people actually use, the people worth following, and the servers where the community meets. You can read all of it before you make an account.","Every page is written for its readers' language, and offers new local hashtags beside the busy English ones, so smaller language communities can grow their own."],moreHeading:"Just want people to follow?",allLanguages:"",tools:"Free tools for Mastodon and Bluesky",follow:"Who to follow on Mastodon",help:"Help",features:"Discover all Mawkingbird features"},de:{title:"Mastodon-Communities nach Interessen: Hashtags, Leute und Server",description:"Finde Mastodon-Communities nach Interessen: die Hashtags und Leute, denen es sich zu folgen lohnt, und die Server, auf denen sich jede Community trifft.",eyebrow:"Communities",openApp:"Mawkingbird \xF6ffnen",heading:"Mastodon-Communities nach Interessen",intro:["Ein neues Mastodon-Konto beginnt mit einer leeren Zeitleiste. Jede Seite hier sammelt ein Interesse: die Hashtags, die Leute wirklich verwenden, die Leute, denen es sich zu folgen lohnt, und die Server, auf denen sich die Community trifft. Du kannst alles lesen, bevor du ein Konto anlegst.","Jede Seite ist f\xFCr deutschsprachige Leserinnen und Leser geschrieben und schl\xE4gt neben den gro\xDFen englischen Hashtags auch deutsche vor, damit kleinere Sprachgemeinschaften wachsen k\xF6nnen."],moreHeading:"Mehr",allLanguages:"Alle Themen in allen Sprachen (auf Englisch)",tools:"Kostenlose Werkzeuge f\xFCr Mastodon und Bluesky",help:"Hilfe (auf Englisch)",features:"Alles, was Mawkingbird kann (auf Englisch)"},fr:{title:"Communaut\xE9s Mastodon par centre d\u2019int\xE9r\xEAt : hashtags, comptes et serveurs",description:"Trouve les communaut\xE9s Mastodon par centre d\u2019int\xE9r\xEAt : les hashtags et les comptes \xE0 suivre, et les serveurs o\xF9 chaque communaut\xE9 se retrouve.",eyebrow:"Communaut\xE9s",openApp:"Ouvrir Mawkingbird",heading:"Communaut\xE9s Mastodon par centre d\u2019int\xE9r\xEAt",intro:["Un nouveau compte Mastodon commence avec un fil vide. Chaque page rassemble un centre d\u2019int\xE9r\xEAt : les hashtags vraiment utilis\xE9s, les comptes \xE0 suivre et les serveurs o\xF9 la communaut\xE9 se retrouve. Tu peux tout lire avant de cr\xE9er un compte.","Chaque page est \xE9crite pour les lecteurs francophones et propose des hashtags en fran\xE7ais \xE0 c\xF4t\xE9 des grands hashtags anglais, pour que les communaut\xE9s francophones grandissent aussi."],moreHeading:"Et aussi",allLanguages:"Tous les sujets, dans toutes les langues (en anglais)",tools:"Outils gratuits pour Mastodon et Bluesky",help:"Aide (en anglais)",features:"Tout ce que fait Mawkingbird (en anglais)"},es:{title:"Comunidades de Mastodon por intereses: hashtags, personas y servidores",description:"Encuentra comunidades de Mastodon por intereses: los hashtags y las personas que vale la pena seguir, y los servidores donde se re\xFAne cada comunidad.",eyebrow:"Comunidades",openApp:"Abrir Mawkingbird",heading:"Comunidades de Mastodon por intereses",intro:["Una cuenta nueva de Mastodon empieza con una cronolog\xEDa vac\xEDa. Cada p\xE1gina re\xFAne un inter\xE9s: los hashtags que la gente usa de verdad, las personas que vale la pena seguir y los servidores donde se re\xFAne la comunidad. Puedes leerlo todo antes de crear una cuenta.","Cada p\xE1gina est\xE1 escrita para lectores en espa\xF1ol y propone hashtags en espa\xF1ol junto a los grandes hashtags en ingl\xE9s, para que las comunidades hispanohablantes tambi\xE9n crezcan."],moreHeading:"M\xE1s",allLanguages:"Todos los temas, en todos los idiomas (en ingl\xE9s)",tools:"Herramientas gratuitas para Mastodon y Bluesky",help:"Ayuda (en ingl\xE9s)",features:"Todo lo que hace Mawkingbird (en ingl\xE9s)"},it:{title:"Comunit\xE0 Mastodon per interesse: hashtag, persone e server",description:"Trova le comunit\xE0 Mastodon per interesse: gli hashtag e le persone da seguire, e i server dove si ritrova ogni comunit\xE0.",eyebrow:"Comunit\xE0",openApp:"Apri Mawkingbird",heading:"Comunit\xE0 Mastodon per interesse",intro:["Un nuovo account Mastodon parte con una timeline vuota. Ogni pagina raccoglie un interesse: gli hashtag che le persone usano davvero, le persone da seguire e i server dove si ritrova la comunit\xE0. Puoi leggere tutto prima di creare un account.","Ogni pagina \xE8 scritta per chi legge in italiano e propone hashtag in italiano accanto ai grandi hashtag in inglese, cos\xEC anche le comunit\xE0 italiane possono crescere."],moreHeading:"Altro",allLanguages:"Tutti gli argomenti, in tutte le lingue (in inglese)",tools:"Strumenti gratuiti per Mastodon e Bluesky",help:"Aiuto (in inglese)",features:"Tutto quello che fa Mawkingbird (in inglese)"},ja:{title:"\u8208\u5473\u5225\u306EMastodon\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\uFF1A\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3001\u4EBA\u3001\u30B5\u30FC\u30D0\u30FC",description:"\u8208\u5473\u304B\u3089Mastodon\u306E\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\u3092\u898B\u3064\u3051\u307E\u3057\u3087\u3046\u3002\u30D5\u30A9\u30ED\u30FC\u3059\u308B\u4FA1\u5024\u306E\u3042\u308B\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3068\u4EBA\u3001\u305D\u3057\u3066\u5404\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\u304C\u96C6\u307E\u308B\u30B5\u30FC\u30D0\u30FC\u3092\u7D39\u4ECB\u3057\u307E\u3059\u3002",eyebrow:"\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3",openApp:"Mawkingbird \u3092\u958B\u304F",heading:"\u8208\u5473\u5225\u306EMastodon\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3",intro:["\u65B0\u3057\u3044Mastodon\u30A2\u30AB\u30A6\u30F3\u30C8\u306E\u30BF\u30A4\u30E0\u30E9\u30A4\u30F3\u306F\u7A7A\u3063\u307D\u304B\u3089\u59CB\u307E\u308A\u307E\u3059\u3002\u5404\u30DA\u30FC\u30B8\u306F\u3072\u3068\u3064\u306E\u8208\u5473\u306B\u3064\u3044\u3066\u3001\u5B9F\u969B\u306B\u4F7F\u308F\u308C\u3066\u3044\u308B\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3001\u30D5\u30A9\u30ED\u30FC\u3059\u308B\u4FA1\u5024\u306E\u3042\u308B\u4EBA\u3001\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\u304C\u96C6\u307E\u308B\u30B5\u30FC\u30D0\u30FC\u3092\u307E\u3068\u3081\u3066\u3044\u307E\u3059\u3002\u30A2\u30AB\u30A6\u30F3\u30C8\u3092\u4F5C\u308B\u524D\u306B\u3059\u3079\u3066\u8AAD\u3081\u307E\u3059\u3002","\u5404\u30DA\u30FC\u30B8\u306F\u65E5\u672C\u8A9E\u306E\u8AAD\u8005\u5411\u3051\u306B\u66F8\u304B\u308C\u3066\u304A\u308A\u3001\u82F1\u8A9E\u306E\u5927\u304D\u306A\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u306B\u52A0\u3048\u3066\u65E5\u672C\u8A9E\u306E\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3082\u63D0\u6848\u3057\u307E\u3059\u3002"],moreHeading:"\u307B\u304B\u306B\u3082",allLanguages:"\u3059\u3079\u3066\u306E\u30C6\u30FC\u30DE\u3068\u3059\u3079\u3066\u306E\u8A00\u8A9E\uFF08\u82F1\u8A9E\uFF09",tools:"Mastodon\u3068Bluesky\u306E\u7121\u6599\u30C4\u30FC\u30EB",help:"\u30D8\u30EB\u30D7\uFF08\u82F1\u8A9E\uFF09",features:"Mawkingbird\u3067\u3067\u304D\u308B\u3053\u3068\uFF08\u82F1\u8A9E\uFF09"}};function t(e){let n=a[e];if(!n)throw new Error(`No communities hub copy for ${e}`);return n}export{a as HUB_COPY,t as hubCopyFor};
